import { CreateJobDto } from '../dto/job/create-job.dto';
import { JobResponseDto } from '../dto/job/job-response.dto';
import { PlantConfigDto } from '../dto/job/plant-config.dto';

export class JobConverter {
  /**
   * Converts a CreateJobDto and other metadata into a JobResponseDto.
   * @param createJobDto request dto
   * @param jobId  job id
   * @param plants  list of plants
   * @returns JobResponseDto
   */
  public static fromCreateDto(
    createJobDto: CreateJobDto,
    jobId: string,
    plants: Record<string, PlantConfigDto>,
  ): JobResponseDto {
    const now = new Date();

    return {
      appId: createJobDto.appId,
      createdAt: now.toDateString(),

      defaultInterval: createJobDto.defaultInterval,
      defaultSchedule: createJobDto.defaultSchedule,
      description: createJobDto.description,
      id: jobId,

      parameters: createJobDto.parameters || {},

      path: createJobDto.path,
      plants,

      service: createJobDto.service,
      type: createJobDto.type,
      updatedAt: now.toDateString(),
    };
  }

  /**
   * Maps an existing Job document (from DB) into a JobResponseDto.
   * @param document the document from cosmos db
   * @returns JobResponseDto the new format of the response
   */
  public static fromDocument(document: JobResponseDto): JobResponseDto {
    return {
      appId: document.appId,
      createdAt: document.createdAt,
      defaultInterval: document.defaultInterval,
      defaultSchedule: document.defaultSchedule,
      description: document.description,
      id: document.id,
      parameters: document.parameters,
      path: document.path,
      plants: document.plants,
      service: document.service,
      type: document.type,
      updatedAt: document.updatedAt,
    };
  }
}

