import { Container, PatchOperation } from '@azure/cosmos';
import { JobsLogContext } from '@mesx/common-lib';
import {
  BadRequestException,
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';

import { CreateJobDto } from '../create-job.dto';
import { JobResponseDto } from '../job-response.dto';
import { JOB_STATUS } from '../job-status.enum';
import { PlantConfigDto } from '../plant-config.dto';
import { PlantUpdateDto } from '../plant-update.dto';
import { JobsQueryHelper } from '../queries/job.query.helper';
import { RescheduleJobDto } from '../reschedule-job.dto';
import { UpdateJobDto } from '../update-job.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseService } from '@/config/cosmos-db/cosmos-database.service';
import { JobConverter } from '@/jobs/converters/job.converter';
import { DaprService } from '@/jobs/services/dapr.service';

@Injectable()
export class JobCommandHelper {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: JobCommandHelper.name, userId };
  }

  private readonly jobContainer: Container;

  public constructor(
    private readonly cosmosService: CosmosDatabaseService,
    private readonly daprService: DaprService,
    private readonly jobsQueryHelper: JobsQueryHelper,
    private readonly logger: AppLogger,
  ) {
    this.jobContainer = this.cosmosService.getContainerJobsDefinition;
  }

  public async createJob(createJobDto: CreateJobDto): Promise<JobResponseDto> {
    const jobId = createJobDto.id;
    const context = JobsQueryHelper.createLogContext('createJob');
    try {
      // Check if job already exists
      await this.jobsQueryHelper.findJobById(jobId);
      throw new ConflictException(`Job with ID '${jobId}' already exists`);
    } catch (error) {
      if (error instanceof ConflictException) {
        throw error;
      }
      if (!(error instanceof NotFoundException)) {
        throw error;
      }
      // Job doesn't exist (NotFoundException), proceed with creation
    }

    const now = new Date().toISOString();

    const plants: Record<string, PlantConfigDto> = {};

    for (const [plantId, plant] of Object.entries(createJobDto.plants)) {
      plants[plantId] = {
        createdAt: now,
        id: plant.id,
        params: plant.params,
        schedule: plant.schedule,
        status: JOB_STATUS.created, // Only inside the plant
        updatedAt: now,
      };
    }

    const jobDocument = JobConverter.fromCreateDto(createJobDto, jobId, plants);

    try {
      this.logger.debug(JSON.stringify(jobDocument, undefined, 2), context);

      const { resource } = await this.jobContainer.items.create(jobDocument);

      this.logger.debug(JSON.stringify(resource, undefined, 2), context);
      if (!resource) {
        throw new BadRequestException(
          `Failed to create job: resource is undefined`,
        );
      }

      return JobConverter.fromDocument(resource);
    } catch (error) {
      this.logger.error(`Failed to create job: ${jobId}`, context, error);
      throw new BadRequestException(`Failed to create job: ${error.message}`);
    }
  }

  public async updateJob(
    jobId: string,
    updateJobDto: UpdateJobDto,
  ): Promise<JobResponseDto> {
    const context = JobsQueryHelper.createLogContext('updateJob');

    this.logger.debug(`Updating job: ${jobId}`, context);

    const existingJob = await this.jobsQueryHelper.findJobById(jobId);

    const updatedJob: JobResponseDto = {
      ...(existingJob as unknown as JobResponseDto),
      appId: updateJobDto.appId ?? existingJob.appId,
      defaultInterval:
        updateJobDto.defaultInterval ?? existingJob.defaultInterval,
      defaultSchedule:
        updateJobDto.defaultSchedule ?? existingJob.defaultSchedule,
      description: updateJobDto.description ?? existingJob.description,
      path: updateJobDto.path ?? existingJob.path,
      service: updateJobDto.service ?? existingJob.service,
      updatedAt: new Date().toISOString(),
    };

    try {
      const { resource } = await this.jobContainer
        .item(jobId, jobId) // â add partition key
        .replace(updatedJob);

      this.logger.debug(`Successfully updated job: ${jobId}`, context);
      if (!resource) {
        throw new NotFoundException(`Job ${jobId} not found after update`);
      }
      return JobConverter.fromDocument(resource);
    } catch (error) {
      this.logger.error(`Failed to update job: ${jobId}`, context, error);
      throw new BadRequestException(`Failed to update job: ${error.message}`);
    }
  }

  public async updateJobPlantConfig(
    jobId: string,
    plantId: number,
    plantConfig: PlantUpdateDto,
  ): Promise<JobResponseDto> {
    const context = JobsQueryHelper.createLogContext('updateJobPlantConfig');

    this.logger.debug(
      `Updating plant ${plantId} config for job: ${jobId}`,
      context,
    );

    // Ensure job exists
    const existingJob = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = existingJob as unknown as JobResponseDto;

    // Ensure plant exists
    if (!jobDocument.plants?.[plantId]) {
      throw new NotFoundException(`Plant ${plantId} not found in job ${jobId}`);
    }

    const now = new Date().toISOString();

    // Construct updated plant
    const updatedPlant = {
      ...jobDocument.plants[plantId],
      ...plantConfig,
      updatedAt: now,
    };
    try {
      // Use PATCH to replace only this plant's config
      const { resource } = await this.jobContainer
        .item(jobId, jobId) // â Add partition key here
        .patch([
          {
            op: 'replace',
            path: `/plants/${plantId}`,
            value: updatedPlant,
          },
          {
            op: 'replace',
            path: '/updatedAt',
            value: now,
          },
        ]);

      this.logger.debug(
        `Successfully patched plant ${plantId} config for job: ${jobId}`,
        context,
      );

      if (!resource) {
        throw new NotFoundException(
          `Plant ${plantId} not found after patch in job ${jobId}`,
        );
      }

      const updatedJobResponse = JobConverter.fromDocument(resource);

      // If plant is active, update the actor via Dapr
      if (updatedPlant.status === JOB_STATUS.active) {
        const plantJob = {
          ...updatedJobResponse,
          plant: {
            id: plantId,
            params: updatedPlant.params,
            schedule: updatedPlant.schedule,
          },
        };

        await this.daprService.reschedulePlantJob(plantJob, plantId);
      }

      return updatedJobResponse;
    } catch (error) {
      this.logger.error(
        `Failed to patch plant config for job: ${jobId}`,
        context,
        error,
      );
      throw new BadRequestException(
        `Failed to patch plant config: ${error.message}`,
      );
    }
  }

  public async rescheduleJob(
    jobId: string,
    rescheduleDto: RescheduleJobDto,
  ): Promise<JobResponseDto> {
    const context = JobsQueryHelper.createLogContext('rescheduleJob');

    this.logger.debug(`Rescheduling job: ${jobId}`, context);

    const job = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = job as unknown as JobResponseDto;

    try {
      // If specific plant is provided, update only that plant's schedule
      if (
        rescheduleDto.plantId !== null &&
        rescheduleDto.plantId !== undefined
      ) {
        const plantKey = String(rescheduleDto.plantId);
        const plant = jobDocument.plants[plantKey];

        if (!plant) {
          throw new NotFoundException(
            `Plant ${rescheduleDto.plantId} not found in job ${jobId}`,
          );
        }

        // Update plant schedule
        const updatedPlantJob = await this.updateJobPlantConfig(
          jobId,
          rescheduleDto.plantId,
          {
            schedule: rescheduleDto.schedule,
          },
        );

        // If plant is active, update the schedule via Dapr
        if (plant.status === JOB_STATUS.active) {
          const plantJob = {
            ...updatedPlantJob,
            plant: {
              id: rescheduleDto.plantId,
              params: plant.params,
              schedule: rescheduleDto.schedule,
            },
          };

          await this.daprService.reschedulePlantJob(
            plantJob,
            rescheduleDto.plantId,
          );
        }

        return updatedPlantJob;
      }

      // Otherwise, update the default schedule for the job
      const updatedJobData = {
        defaultSchedule: rescheduleDto.schedule,
      };
      const updatedJob = await this.updateJob(jobId, updatedJobData);

      // For active plants without custom schedules, update schedules via Dapr
      const activePlants = Object.values(jobDocument.plants).filter(
        (p) => p.status === JOB_STATUS.active && !p.schedule,
      );

      const updatePromises = activePlants.map((plant) => {
        const plantJob = {
          ...updatedJob,
          plant: {
            id: plant.id,
            params: plant.params,
            schedule: rescheduleDto.schedule,
          },
        };

        return this.daprService.reschedulePlantJob(plantJob, plant.id);
      });

      await Promise.all(updatePromises);

      return updatedJob;
    } catch (error) {
      this.logger.error(`Failed to reschedule job: ${jobId}`, context, error);
      throw new BadRequestException(
        `Failed to reschedule job: ${error.message}`,
      );
    }
  }

  public async addPlantToJob(
    jobId: string,
    newPlant: PlantConfigDto,
  ): Promise<void> {
    try {
      const plantId = String(newPlant.id);

      const patchOperations: Array<PatchOperation> = [
        {
          op: 'set',
          path: `/plants/${plantId}`,
          value: {
            ...newPlant,
            createdAt: newPlant.createdAt ?? new Date().toISOString(),
            status: newPlant.status ?? 'created',
            updatedAt: new Date().toISOString(),
          },
        },
      ];
      await this.jobContainer
        .item(jobId, jobId) // â add partition key
        .patch(patchOperations);
    } catch (error) {
      console.error('Error adding plant to job:', error);
      throw error;
    }
  }
}

