import { Container } from '@azure/cosmos';
import { DaprClient, HttpMethod } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { JobResponseDto } from '../job-response.dto';
import { PlantIngestionResponseDto } from '../plant-ingestion-response-dto';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseService } from '@/config/cosmos-db/cosmos-database.service';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
import { JobConverter } from '@/jobs/converters/job.converter';

@Injectable()
export class JobsQueryHelper {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: JobsQueryHelper.name, userId };
  }

  private readonly daprClient = new DaprClient();

  private readonly jobContainer: Container;

  public constructor(
    private readonly cosmosService: CosmosDatabaseService,
    private readonly urlApiConfigService: UrlApiConfigService,
    private readonly logger: AppLogger,
  ) {
    this.jobContainer = this.cosmosService.getContainerJobsDefinition;
  }

  public async findAllJobs(plantId?: string): Promise<Array<JobResponseDto>> {
    const context = JobsQueryHelper.createLogContext(
      'findAllJobs',
      Number(plantId),
    );
    try {
      let query = 'SELECT * FROM c WHERE IS_DEFINED(c.appId)';

      if (plantId) {
        query += ` and ARRAY_CONTAINS(c.plants, { id: ${plantId} }, true)`;
      }

      const { resources } = await this.jobContainer.items
        .query(query)
        .fetchAll();
      return resources.map(
        (document): JobResponseDto => JobConverter.fromDocument(document),
      );
    } catch (error) {
      this.logger.error('Failed to fetch jobs', context, error);
      throw new BadRequestException(`Failed to fetch jobs: ${error.message}`);
    }
  }

  public async findJobById(
    jobId: string,
    plantId?: number,
  ): Promise<JobResponseDto> {
    try {
      const context = JobsQueryHelper.createLogContext(
        'findJobById',
        Number(plantId),
      );
      // Since we're not using partition keys, we need to query by id
      const { resources } = await this.jobContainer.items
        .query(`SELECT * FROM c WHERE c.id = '${jobId}'`)
        .fetchAll();

      if (!resources || resources.length === 0) {
        this.logger.warn(
          `Resource is null/undefined for document ID: ${jobId}`,
          context,
        );
        throw new NotFoundException(`Job with ID '${jobId}' not found`);
      }

      const resource = resources[0];

      // If plantId is provided, check if this plant exists in the job
      if (plantId && !resource.plants?.[plantId]) {
        throw new NotFoundException(
          `Plant ${plantId} not found in job ${jobId}`,
        );
      }

      return JobConverter.fromDocument(resource);
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }

      this.logger.error(`Failed to find job: ${jobId}`, error);
      throw new NotFoundException(`Job with ID '${jobId}' not found`);
    }
  }

  public async getPlants(): Promise<Array<PlantIngestionResponseDto>> {
    const result = await this.daprClient.invoker.invoke(
      this.urlApiConfigService.plantHierarchyApiAppId,
      'plant/plants',
      HttpMethod.GET,
      undefined,
      {
        headers: {
          authorization: `Bearer ${process.env.TOKEN}`,
        },
      },
    );

    // Cast the result to the proper DTO array
    return result as Array<PlantIngestionResponseDto>;
  }
}

