import * as path from 'node:path';
import { Container } from '@azure/cosmos';
import { Injectable, Logger, OnApplicationBootstrap } from '@nestjs/common';
import { readJSON } from 'fs-extra'; // <-- named import
import { globby } from 'globby'; // <-- named import
import { JobsService } from './services/jobs.service';
import { CosmosDatabaseService } from '@/config/cosmos-db/cosmos-database.service';

@Injectable()
export class JobMigrationService implements OnApplicationBootstrap {
  private readonly logger = new Logger(JobMigrationService.name);

  private readonly jobsContainer: Container;

  private readonly migrationsLogContainer: Container;

  public constructor(
    private readonly cosmosService: CosmosDatabaseService,
    private readonly jobsService: JobsService,
  ) {
    this.jobsContainer = this.cosmosService.getContainerJobsDefinition;
    this.migrationsLogContainer = this.cosmosService.getContainerJobsDefinition;
  }

  public async onApplicationBootstrap(): Promise<void> {
    this.logger.log('Running job migrations...');
    await this.runMigrations();
  }

  private async runMigrations(): Promise<void> {
    // Fetch all JSON migration files
    const migrationsDirectory = path.join(__dirname, 'migrations'); // __dirname points to dist/jobs
    const migrationFiles = await globby(`${migrationsDirectory}/*.json`);
    if (migrationFiles.length === 0) {
      this.logger.warn('No migration files found.');
      return;
    }

    for (const file of migrationFiles) {
      try {
        const migration = await readJSON(file); // <-- use named import
        const migrationName = String(
          file
            .split('/')
            .pop()
            ?.replace(/\.json$/, ''),
        );

        if (migration?.id) {
          const { resource } = await this.migrationsLogContainer
            .item(migrationName)
            .read();

          if (resource) {
            this.logger.log(
              `Migration ${migrationName} already executed. Skipping.`,
            );
          } else {
            this.logger.log(`Creating job from migration: ${migrationName}`);
            await this.jobsService.createJob(migration);

            // Log migration run
            await this.migrationsLogContainer.items.create({
              id: migrationName,
              runAt: new Date().toISOString(),
            });

            this.logger.log(`Migration ${migrationName} completed.`);
          }
        } else {
          this.logger.warn(`Migration file ${file} missing 'id'. Skipping.`);
        }
      } catch (error) {
        this.logger.error(
          `Failed to process migration ${file}: ${error.message}`,
        );
      }
    }

    this.logger.log('All job migrations processed.');
  }
}

