@ApiTags('Jobs')
@Controller('jobs')
export class JobsController {
  private readonly logger = new Logger(JobsController.name);

  public constructor(
    private readonly jobsService: JobsService,
    private readonly activateJob: ActivateJob,
    private readonly deactivateJob: DeactivateJob,
    private readonly executeJobImmediately: ExecuteJobImmediately,
    private readonly jobHistoryService: JobHistoryService,
  ) {}

  @Post()
  @ApiOperation({ summary: 'Create a new job' })
  @ApiBody({ type: CreateJobDto })
  @ApiResponse({
    description: 'The job has been successfully created.',
    status: 201,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Bad Request.', status: 400 })
  @ApiResponse({ description: 'Job already exists.', status: 409 })
  public async createJob(
    @Body() createJobDto: CreateJobDto,
  ): Promise<JobResponseDto> {
    return this.jobsService.createJob(createJobDto);
  }

  @Get('/plants')
  public async getPlants(): Promise<Array<PlantIngestionResponseDto>> {
    return this.jobsService.getPlants();
  }

  @Get()
  @ApiOperation({ summary: 'Get all jobs' })
  @ApiQuery({
    description: 'Filter jobs by plant ID',
    name: 'plantId',
    required: false,
  })
  @ApiResponse({
    description: 'List of jobs retrieved successfully.',
    status: 200,
    type: [JobResponseDto],
  })
  public async findAllJobs(
    @Query('plantId') plantId?: string,
  ): Promise<Array<JobResponseDto>> {
    return this.jobsService.findAllJobs(plantId);
  }

  @Get(':jobId')
  @ApiOperation({ summary: 'Get a job by ID' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiResponse({
    description: 'Job retrieved successfully.',
    status: 200,
    type: JobResponseDto,
  })
  public async findJobById(
    @Param('jobId') jobId: string,
  ): Promise<JobResponseDto> {
    return this.jobsService.findJobById(jobId);
  }

  @Patch(':jobId')
  @ApiOperation({ summary: 'Update a job' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiBody({ type: UpdateJobDto })
  @ApiResponse({
    description: 'Job updated successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({ description: 'Bad Request.', status: 400 })
  public async updateJob(
    @Param('jobId') jobId: string,
    @Body() updateJobDto: UpdateJobDto,
  ): Promise<JobResponseDto> {
    return this.jobsService.updateJob(jobId, updateJobDto);
  }

  @Patch(':jobId/plant/:plantId')
  @ApiOperation({ summary: 'Update a specific plant configuration in a job' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiParam({ description: 'Plant ID', name: 'plantId' })
  @ApiBody({ type: PlantUpdateDto })
  @ApiResponse({
    description: 'Plant configuration updated successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job or plant not found.', status: 404 })
  @ApiResponse({ description: 'Bad Request.', status: 400 })
  public async updateJobPlantConfig(
    @Param('jobId') jobId: string,
    @Param('plantId', ParseIntPipe) plantId: number,
    @Body() plantConfig: PlantUpdateDto,
  ): Promise<JobResponseDto> {
    return this.jobsService.updateJobPlantConfig(jobId, plantId, plantConfig);
  }

  @Delete(':jobId')
  @ApiOperation({ summary: 'Delete a job' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiResponse({
    description: 'Job deleted successfully.',
    status: 204,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({
    description: 'Cannot delete job with active plants.',
    status: 400,
  })
  @HttpCode(HttpStatus.NO_CONTENT)
  public async deleteJob(@Param('jobId') jobId: string): Promise<void> {
    return this.deactivateJob.deleteJob(jobId);
  }

  @Delete(':jobId/plant/:plantId')
  @ApiOperation({ summary: 'Delete a specific plant from a job' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiParam({ description: 'Plant ID', name: 'plantId' })
  @ApiResponse({
    description: 'Plant deleted from job successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job or plant not found.', status: 404 })
  @ApiResponse({
    description: 'Cannot delete active plant. Please stop the plant first.',
    status: 400,
  })
  public async deletePlantFromJob(
    @Param('jobId') jobId: string,
    @Param('plantId', ParseIntPipe) plantId: number,
  ): Promise<JobResponseDto> {
    return this.deactivateJob.deletePlantFromJob(jobId, plantId);
  }

  @Post(':jobId/activate')
  @ApiOperation({ summary: 'Activate a job for specific or all plants' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiBody({ type: PlantJobActivateDto })
  @ApiResponse({
    description: 'Job plants activated successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({
    description: 'Plants are already active or cannot be activated.',
    status: 400,
  })
  public async activateJobPlants(
    @Param('jobId') jobId: string,
    @Body() activateDto: PlantJobActivateDto,
  ): Promise<JobResponseDto> {
    try {
      const result = await this.activateJob.activateJobPlants(
        jobId,
        activateDto,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `[JobsController] Activation failed for job: ${jobId}`,
        error,
      );
      throw error;
    }
  }

  @Post(':jobId/plant/:plantId/stop')
  @ApiOperation({ summary: 'Stop a job for a specific plant' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiParam({ description: 'Plant ID', name: 'plantId' })
  @ApiResponse({
    description: 'Job stopped for the specified plant successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job or plant not found.', status: 404 })
  @ApiResponse({ description: 'Plant job is not active.', status: 400 })
  public async stopJobPlant(
    @Param('jobId') jobId: string,
    @Param('plantId', ParseIntPipe) plantId: number,
  ): Promise<JobResponseDto> {
    return this.deactivateJob.stopJobPlant(jobId, plantId);
  }

  @Post(':jobId/deactivate')
  @ApiOperation({ summary: 'Stop a job for all or specific plants' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiBody({ type: PlantJobActivateDto })
  @ApiResponse({
    description: 'Job plants deactivated successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({ description: 'No active plants to stop.', status: 400 })
  public async deactivateJobPlants(
    @Param('jobId') jobId: string,
    @Body() deactivateDto: PlantJobActivateDto,
  ): Promise<JobResponseDto> {
    try {
      const result = await this.deactivateJob.deactivateJobPlants(
        jobId,
        deactivateDto,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `[JobsController] Deactivation failed for job: ${jobId}`,
        error,
      );
      throw error;
    }
  }

  @Post(':jobId/reschedule')
  @ApiOperation({ summary: 'Reschedule a job or a specific plant in a job' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiBody({ type: RescheduleJobDto })
  @ApiResponse({
    description: 'Job rescheduled successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({ description: 'Bad Request.', status: 400 })
  public async rescheduleJob(
    @Param('jobId') jobId: string,
    @Body() rescheduleDto: RescheduleJobDto,
  ): Promise<JobResponseDto> {
    return this.jobsService.rescheduleJob(jobId, rescheduleDto);
  }

  @Post(':jobId/execute')
  @ApiOperation({
    summary: 'Execute a job immediately for specific or all plants',
  })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiBody({ type: PlantJobActivateDto })
  @ApiResponse({
    description: 'Job executed immediately successfully.',
    status: 200,
    type: JobResponseDto,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({ description: 'Job execution failed.', status: 400 })
  public async executeJobNow(
    @Param('jobId') jobId: string,
    @Body() executeDto: PlantJobActivateDto,
  ): Promise<JobResponseDto> {
    try {
      const result = await this.executeJobImmediately.executeJobImmediately(
        jobId,
        executeDto,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `[JobsController] Immediate execution failed for job: ${jobId}`,
        error,
      );
      throw error;
    }
  }

  @Get(':jobId/plant/:plantId/history')
  @ApiOperation({
    summary: 'Get execution history for a specific plant in a job',
  })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiParam({ description: 'Plant ID', name: 'plantId' })
  @ApiQuery({
    description: 'Maximum number of records to return',
    name: 'limit',
    required: false,
    type: Number,
  })
  @ApiResponse({
    description: 'Plant job execution history retrieved successfully.',
    status: 200,
    type: [JobExecutionHistoryDto],
  })
  @ApiResponse({ description: 'Job or plant not found.', status: 404 })
  public async getPlantJobHistory(
    @Param('jobId') jobId: string,
    @Param('plantId') plantId: string,
    @Query('limit') limit?: number,
  ): Promise<Array<JobExecutionHistoryDto>> {
    // First check if job and plant exist
    // Then get the history
    return this.jobHistoryService.getJobPlantExecutionHistory(
      jobId,
      plantId,
      limit ? Number(limit) : 10,
    );
  }

  @Post(':jobId/plant')
  @ApiOperation({ summary: 'Add a new plant to a job' })
  @ApiParam({ description: 'Job ID', name: 'jobId' })
  @ApiBody({ type: PlantConfigDto })
  @ApiResponse({
    description: 'Plant added to job successfully.',
    status: 200,
  })
  @ApiResponse({ description: 'Job not found.', status: 404 })
  @ApiResponse({ description: 'Bad Request.', status: 400 })
  public async addPlantToJob(
    @Param('jobId') jobId: string,
    @Body() plantConfig: PlantConfigDto,
  ): Promise<void> {
    this.jobsService.addPlantToJob(jobId, plantConfig);
  }
}

