import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, BadRequestException } from '@nestjs/common';
import { JobResponseDto } from '../dto/job/job-response.dto';
import { JOB_STATUS } from '../dto/job/job-status.enum';
import { PlantJobActivateDto } from '../dto/job/plant-job-activate.dto';
import { JobsQueryHelper } from '../dto/job/queries/job.query.helper';
import { DaprService } from './dapr.service';
import { PlantOperationsHelper } from './plant-operations.helper';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class ActivateJob {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: ActivateJob.name, userId };
  }

  public constructor(
    private readonly jobsQueryHelper: JobsQueryHelper,
    private readonly daprService: DaprService,
    private readonly plantHelper: PlantOperationsHelper,
    private readonly logger: AppLogger,
  ) {}

  public async activateJobPlants(
    jobId: string,
    activateDto: PlantJobActivateDto,
  ): Promise<JobResponseDto> {
    const context = ActivateJob.createLogContext(
      'activateJobPlants',
      undefined,
      jobId,
    );
    this.logger.debug(
      `[JobsService] Starting activation for job: ${jobId}`,
      context,
    );
    this.logger.debug(
      `[JobsService] Activation request: ${JSON.stringify(activateDto)}`,
      context,
    );

    const job = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = job as unknown as JobResponseDto;

    const plantCount = Object.keys(jobDocument.plants || {}).length;
    this.logger.debug(
      `[JobsService] Job found with ${plantCount} plants`,
      context,
    );

    // Determine which plants to activate
    const plantsToActivate = this.plantHelper.determinePlantsToProcess(
      activateDto,
      jobDocument,
      jobId,
      false,
    );

    // Filter out already active plants
    const plantsToProcess = this.plantHelper.filterPlantsByStatus(
      plantsToActivate,
      jobDocument,
      JOB_STATUS.active,
      false,
    );

    if (plantsToProcess.length === 0) {
      this.logger.debug(
        `[JobsService] No plants to activate for job: ${jobId}`,
        context,
      );
      return jobDocument;
    }

    this.logger.debug(
      `[JobsService] Processing ${plantsToProcess.length} plants for activation`,
      context,
    );

    try {
      const activationResults: Array<{
        plantId: number;
        success: boolean;
        error?: string;
      }> = [];

      for (const plantId of plantsToProcess) {
        this.logger.debug(
          `[JobsService] Starting activation for plant ${plantId}`,
          context,
        );

        try {
          // Find the plant in the job
          const plant = jobDocument.plants[plantId];
          if (!plant) {
            throw new Error(`Plant ${plantId} not found in job ${jobId}`);
          }

          // Create a job object for this specific plant
          const plantJob = {
            ...job,
            plant: {
              id: plantId,
              interval: plant.interval,
              params: plant.params,
              schedule: plant.schedule,
            },
          };

          // Activate the job for this plant via DAPR
          const daprResult = await this.daprService.activatePlantJob(
            plantJob,
            plantId,
          );
          this.logger.debug(
            `[JobsService] DAPR activation result for plant ${plantId}: ${JSON.stringify(
              daprResult,
            )}`,
            context,
          );

          // Update plant status to ACTIVE only after successful DAPR call
          await this.plantHelper.updatePlantStatus(
            jobId,
            plantId,
            JOB_STATUS.active,
          );

          activationResults.push({ plantId, success: true });
          this.logger.debug(
            `[JobsService] Successfully activated plant ${plantId}`,
            context,
          );
        } catch (plantError) {
          this.logger.error(
            `[JobsService] Failed to activate plant ${plantId}:`,
            context,
          );
          activationResults.push({
            error: plantError.message,
            plantId,
            success: false,
          });
        }
      }

      this.plantHelper.logOperationSummary(
        activationResults,
        jobId,
        'Activation',
      );

      const successfulActivations = activationResults.filter((r) => r.success);
      if (successfulActivations.length === 0) {
        const failedActivations = activationResults.filter((r) => !r.success);
        const errorMessages = failedActivations.map(
          (r) => `Plant ${r.plantId}: ${r.error}`,
        );
        throw new BadRequestException(
          `Failed to activate any plants. Errors: ${errorMessages.join('; ')}`,
        );
      }

      const updatedJob = await this.jobsQueryHelper.findJobById(jobId);

      this.logger.debug(
        `[JobsService] Completed plant activation for job: ${jobId}`,
        context,
      );

      if (activationResults.some((r) => !r.success)) {
        this.logger.warn(
          `[JobsService] Partial success: ${successfulActivations.length}/${plantsToProcess.length} plants activated successfully`,
          context,
        );
      }

      return updatedJob;
    } catch (error) {
      throw new BadRequestException(
        `Failed to activate plants: ${error.message}`,
      );
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JobResponseDto } from '../dto/job/job-response.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';

@Injectable()
export class DaprService {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprService.name, userId };
  }

  private readonly daprPort: string;

  private readonly actorType: string;

  private readonly daprBaseUrl: string;

  public constructor(
    private readonly configService: ConfigService,
    private readonly urlApiConfigService: UrlApiConfigService,
    private readonly logger: AppLogger,
  ) {
    this.actorType = this.configService.get<string>(
      'JOB_ACTOR_TYPE',
      'JobActor',
    );
    this.daprBaseUrl = this.urlApiConfigService.daprActorUrl;
  }

  private getActorId(job: JobResponseDto, plantId?: number): string {
    const context = DaprService.createLogContext('getActorId', plantId);
    // Using this to satisfy the class-methods-use-this rule
    const debugMessage = plantId
      ? `Creating actor ID for job ${job.id} and plant ${plantId}`
      : `Creating actor ID for job ${job.id}`;
    this.logger.debug(debugMessage, context);
    return plantId ? `${job.id}-${plantId}` : job.id;
  }

  /**
   * Generic method to invoke actor methods via the Dapr HTTP API
   * @param actorId The actor ID
   * @param method The method name to invoke
   * @param data The data to pass to the method
   * @returns Promise with the response from the actor method
   */
  private async invokeActorMethod(
    actorId: string,
    method: string,
    data: Record<string, unknown>,
  ): Promise<Record<string, unknown>> {
    const startTime = Date.now();
    const context = DaprService.createLogContext('invokeActorMethod');

    try {
      const url = `${this.daprBaseUrl}/${actorId}/method/${method}`;

      this.logger.debug(
        `[DaprService] Invoking actor method ${method} at ${url}`,
        context,
      );
      this.logger.debug(`[DaprService] Actor ID: ${actorId}`, context);
      this.logger.debug(
        `[DaprService] Request payload: ${JSON.stringify(data, null, 2)}`,
        context,
      );

      const response = await fetch(url, {
        body: JSON.stringify(data),
        headers: {
          contentType: 'application/json',
        },
        method: 'POST',
      });

      const duration = Date.now() - startTime;
      this.logger.debug(
        `[DaprService] Actor method ${method} completed in ${duration}ms with status: ${response.status}`,
        context,
      );

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Actor method invocation failed: ${response.status} - ${errorText}`,
        );
      }

      // For methods that return no content
      if (response.status === 204) {
        this.logger.debug(
          `[DaprService] Actor method ${method} returned no content (204)`,
          context,
        );
        return { success: true };
      }

      const responseData = (await response.json()) as Record<string, unknown>;
      this.logger.debug(
        `[DaprService] Actor method ${method} response: ${JSON.stringify(responseData, null, 2)}`,
        context,
      );

      return responseData;
    } catch (error) {
      const duration = Date.now() - startTime;
      this.logger.error(
        `[DaprService] Error invoking actor method ${method} after ${duration}ms:`,
        context,
        error,
      );
      throw error;
    }
  }

  public async activateJob(
    job: JobResponseDto,
  ): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job);
    const context = DaprService.createLogContext('activateJob');

    try {
      this.logger.debug(
        `Activating actor ${this.actorType}/${actorId} for job ${job.id}`,
        context,
      );

      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, 'activate', { job });

      this.logger.debug(
        `Successfully activated actor ${this.actorType}/${actorId} for job ${job.id}`,
        context,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to activate actor ${this.actorType}/${actorId} for job ${job.id}:`,
        context,
        error,
      );
      throw error;
    }
  }

  public async activatePlantJob(
    job: JobResponseDto,
    plantId: number,
  ): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job, plantId);
    const context = DaprService.createLogContext('activatePlantJob', plantId);
    try {
      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, 'activate', { job });
      return result;
    } catch (error) {
      this.logger.error(
        `[DaprService] Failed to activate actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}:`,
        context,
        error,
      );
      throw error;
    }
  }

  public async stopJob(job: JobResponseDto): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job);
    const context = DaprService.createLogContext('stopJob');
    try {
      this.logger.debug(
        `Stopping actor ${this.actorType}/${actorId} for job ${job.id}`,
        context,
      );

      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, 'stop', { job });

      this.logger.debug(
        `Successfully stopped actor ${this.actorType}/${actorId} for job ${job.id}`,
        context,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to stop actor ${this.actorType}/${actorId} for job ${job.id}:`,
        context,
        error,
      );
      throw error;
    }
  }

  public async stopPlantJob(
    job: JobResponseDto,
    plantId: number,
  ): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job, plantId);
    const context = DaprService.createLogContext('stopPlantJob', plantId);
    try {
      this.logger.debug(
        `[DaprService] Stopping actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}`,
        context,
      );
      this.logger.debug(
        `[DaprService] Job data being sent: ${JSON.stringify(job, null, 2)}`,
        context,
      );

      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, 'stop', { job });

      this.logger.debug(
        `[DaprService] Successfully stopped actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}`,
        context,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `[DaprService] Failed to stop actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}:`,
        context,
        error,
      );
      throw error;
    }
  }

  public async rescheduleJob(
    job: JobResponseDto,
  ): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job);
    const context = DaprService.createLogContext('rescheduleJob');
    try {
      this.logger.debug(
        `Rescheduling actor ${this.actorType}/${actorId} for job ${job.id}`,
        context,
      );

      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, 'reschedule', {
        job,
      });

      this.logger.debug(
        `Successfully rescheduled actor ${this.actorType}/${actorId} for job ${job.id}`,
        context,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to reschedule actor ${this.actorType}/${actorId} for job ${job.id}:`,
        context,
        error,
      );
      throw error;
    }
  }

  public async reschedulePlantJob(
    job: JobResponseDto,
    plantId: number,
  ): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job, plantId);
    const context = DaprService.createLogContext('reschedulePlantJob', plantId);
    try {
      this.logger.debug(
        `Rescheduling actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}`,
        context,
      );

      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, 'reschedule', {
        job,
      });

      this.logger.debug(
        `Successfully rescheduled actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}`,
        context,
      );
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to reschedule actor ${this.actorType}/${actorId} for job ${job.id} plant ${plantId}:`,
        context,
        error,
      );
      throw error;
    }
  }

  // Generic method if you want to support dynamic operations
  public async invokeJobActor(
    operation: string,
    job: JobResponseDto,
    plantId?: number,
  ): Promise<Record<string, unknown>> {
    const actorId = this.getActorId(job, plantId);
    const context = DaprService.createLogContext('invokeJobActor', plantId);
    try {
      const plantMessage = plantId ? ` plant ${plantId}` : '';
      this.logger.debug(
        `Invoking ${operation} on actor ${this.actorType}/${actorId} for job ${job.id}${plantMessage}`,
        context,
      );

      // Pass the job wrapped in an object with a job property
      const result = await this.invokeActorMethod(actorId, operation, { job });

      this.logger.debug(
        `Successfully invoked ${operation} on actor ${this.actorType}/${actorId} for job ${job.id}${plantMessage}`,
        context,
      );
      return result;
    } catch (error) {
      const plantMessage = plantId ? ` plant ${plantId}` : '';
      this.logger.error(
        `Failed to invoke ${operation} on actor ${this.actorType}/${actorId} for job ${job.id}${plantMessage}:`,
        context,
        error,
      );
      throw error;
    }
  }
}

import { Container } from '@azure/cosmos';
import { JobsLogContext } from '@mesx/common-lib';
import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { CosmosDatabaseService } from '../../config/cosmos-db/cosmos-database.service';
import { JobConverter } from '../converters/job.converter';
import { JobResponseDto } from '../dto/job/job-response.dto';
import { JOB_STATUS } from '../dto/job/job-status.enum';
import { PlantJobActivateDto } from '../dto/job/plant-job-activate.dto';
import { JobsQueryHelper } from '../dto/job/queries/job.query.helper';
import { DaprService } from './dapr.service';
import { PlantOperationsHelper } from './plant-operations.helper';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class DeactivateJob {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DeactivateJob.name, userId };
  }

  private readonly jobContainer: Container;

  public constructor(
    private readonly jobsQueryHelper: JobsQueryHelper,
    private readonly cosmosService: CosmosDatabaseService,
    private readonly daprService: DaprService,
    private readonly plantHelper: PlantOperationsHelper,
    private readonly logger: AppLogger,
  ) {
    this.jobContainer = this.cosmosService.getContainerJobsDefinition;
  }

  public async deleteJob(jobId: string): Promise<void> {
    const context = DeactivateJob.createLogContext('deleteJob');
    this.logger.debug(`Deleting job: ${jobId}`, context);

    // Check if job exists and has no active plants
    const existingJob = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = existingJob as unknown as JobResponseDto;

    const hasActivePlants = Object.values(jobDocument.plants).some(
      (plant) => plant.status === JOB_STATUS.active,
    );

    if (hasActivePlants) {
      throw new BadRequestException(
        'Cannot delete a job with active plants. Please stop all plants first.',
      );
    }

    try {
      await this.jobContainer.item(jobId).delete();

      this.logger.debug(`Successfully deleted job: ${jobId}`, context);
    } catch (error) {
      this.logger.error(`Failed to delete job: ${jobId}`, context, error);
      throw new BadRequestException(`Failed to delete job: ${error.message}`);
    }
  }

  public async stopJobPlant(
    jobId: string,
    plantId: number,
  ): Promise<JobResponseDto> {
    const context = DeactivateJob.createLogContext('stopJobPlant', plantId);
    this.logger.debug(`Stopping plant ${plantId} for job: ${jobId}`, context);

    const job = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = job as unknown as JobResponseDto;

    // Find the plant in the job
    const plant = jobDocument.plants?.[plantId];
    if (!plant) {
      throw new NotFoundException(`Plant ${plantId} not found in job ${jobId}`);
    }

    if (plant.status !== JOB_STATUS.active) {
      throw new BadRequestException(`Plant ${plantId} is not active`);
    }

    try {
      // Create a job object for this specific plant
      const plantJob = {
        ...job,
        plant: {
          id: plantId,
          params: plant.params,
        },
      };

      // Stop the job for this plant via Dapr
      await this.daprService.stopPlantJob(plantJob, plantId);

      // Update plant status to STOPPED
      const updatedJob = await this.plantHelper.updatePlantStatus(
        jobId,
        plantId,
        JOB_STATUS.stopped,
      );

      this.logger.debug(
        `Successfully stopped plant ${plantId} for job: ${jobId}`,
        context,
      );
      return updatedJob;
    } catch (error) {
      this.logger.error(
        `Failed to stop plant ${plantId} for job: ${jobId}`,
        context,
        error,
      );
      throw new BadRequestException(`Failed to stop plant: ${error.message}`);
    }
  }

  public async deactivateJobPlants(
    jobId: string,
    deactivateDto: PlantJobActivateDto,
  ): Promise<JobResponseDto> {
    const context = DeactivateJob.createLogContext('deactivateJobPlants');
    this.logger.debug(
      `[JobsService] Starting deactivation for job: ${jobId}`,
      context,
    );
    this.logger.debug(
      `[JobsService] Deactivation request: ${JSON.stringify(deactivateDto)}`,
      context,
    );

    const job = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = job as unknown as JobResponseDto;

    const plantKeys = Object.keys(jobDocument.plants);
    this.logger.debug(
      `[JobsService] Job found with ${plantKeys.length} plants`,
      context,
    );

    // ð¨ Block if job is running unless force=true
    if (
      !deactivateDto.force &&
      jobDocument.plants &&
      Object.values(jobDocument.plants).some(
        (plant) => plant.status === JOB_STATUS.running,
      )
    ) {
      throw new BadRequestException(
        `Cannot deactivate plants while job ${jobId} is running.`,
      );
    }

    // Pick which plants to deactivate
    const plantsToDeactivate = this.plantHelper.determinePlantsToProcess(
      deactivateDto,
      jobDocument,
      jobId,
      true, // Only consider active plants
    );

    if (plantsToDeactivate.length === 0) {
      throw new BadRequestException('No active plants to deactivate');
    }

    this.logger.debug(
      `[JobsService] Found ${plantsToDeactivate.length} plants for deactivation`,
      context,
    );

    // â If force = true â fire and forget
    if (deactivateDto.force) {
      this.logger.warn(
        `[JobsService] Force deactivation enabled for job ${jobId}. Returning immediately, processing continues in background.`,
        context,
      );

      (async (): Promise<void> => {
        try {
          await this.processDeactivation(
            jobId,
            plantsToDeactivate,
            jobDocument,
            job,
          );
        } catch (error) {
          this.logger.error(
            `[JobsService] Background deactivation failed for job ${jobId}:`,
            context,
            error,
          );
        }
      })();

      // Return job state immediately (client knows it's still deactivating)
      return {
        ...jobDocument,
        description: jobDocument.description ?? '',
      };
    }

    // ð Default synchronous deactivation
    await this.processDeactivation(jobId, plantsToDeactivate, jobDocument, job);

    const updatedJob = await this.jobsQueryHelper.findJobById(jobId);

    this.logger.debug(
      `[JobsService] Completed plant deactivation for job: ${jobId}`,
      context,
    );

    return updatedJob;
  }

  // ð¹ Extracted helper method
  private async processDeactivation(
    jobId: string,
    plantsToDeactivate: Array<number>,
    jobDocument: JobResponseDto,
    job: JobResponseDto,
  ): Promise<void> {
    const deactivationResults: Array<{
      plantId: number;
      success: boolean;
      error?: string;
    }> = [];
    const context = DeactivateJob.createLogContext('processDeactivation');
    for (const plantId of plantsToDeactivate) {
      this.logger.debug(
        `[JobsService] Starting deactivation for plant ${plantId}`,
        context,
      );
      try {
        const plant = jobDocument.plants[plantId.toString()];
        if (!plant) {
          throw new Error(`Plant ${plantId} not found in job ${jobId}`);
        }

        const plantJob = {
          ...job,
          plant: {
            id: plantId,
            interval: plant.interval,
            params: plant.params,
            schedule: plant.schedule,
          },
        };

        await this.daprService.stopPlantJob(plantJob, plantId);

        await this.plantHelper.updatePlantStatus(
          jobId,
          plantId,
          JOB_STATUS.stopped,
        );

        deactivationResults.push({ plantId, success: true });
      } catch (error) {
        this.logger.error(
          `[JobsService] Failed to deactivate plant ${plantId}:`,
          context,
          error,
        );
        deactivationResults.push({
          error: error.message,
          plantId,
          success: false,
        });
      }
    }

    this.plantHelper.logOperationSummary(
      deactivationResults,
      jobId,
      'Deactivation',
    );

    const successful = deactivationResults.filter((r) => r.success);
    if (successful.length === 0) {
      const errors = deactivationResults
        .filter((r) => !r.success)
        .map((r) => `Plant ${r.plantId}: ${r.error}`);
      throw new BadRequestException(
        `Failed to deactivate any plants. Errors: ${errors.join('; ')}`,
      );
    }

    if (deactivationResults.some((r) => !r.success)) {
      this.logger.warn(
        `[JobsService] Partial success: ${successful.length}/${plantsToDeactivate.length} plants deactivated successfully`,
        context,
      );
    }
  }

  public async deletePlantFromJob(
    jobId: string,
    plantId: number,
  ): Promise<JobResponseDto> {
    const context = DeactivateJob.createLogContext(
      'deletePlantFromJob',
      plantId,
    );
    this.logger.debug(`Deleting plant ${plantId} from job: ${jobId}`, context);

    const job = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = job as unknown as JobResponseDto;
    if (
      jobDocument.plants &&
      Object.values(jobDocument.plants).some(
        (plant) => plant.status === JOB_STATUS.running,
      )
    ) {
      throw new BadRequestException(
        `Cannot deactivate plants while job ${jobId} is running.`,
      );
    }
    const plantKey = String(plantId);

    // Check if plant exists
    if (!jobDocument.plants[plantKey]) {
      throw new NotFoundException(`Plant ${plantId} not found in job ${jobId}`);
    }

    // Check if plant is active - can't delete active plants
    if (jobDocument.plants[plantKey].status === JOB_STATUS.active) {
      throw new BadRequestException(
        `Cannot delete active plant ${plantId}. Please stop the plant first.`,
      );
    }

    try {
      // Remove the plant from the record
      delete jobDocument.plants[plantKey];
      jobDocument.updatedAt = new Date().toISOString();

      const { resource } = await this.jobContainer
        .item(jobId, jobId) // â add the partition key (same value)
        .replace(jobDocument);

      this.logger.debug(
        `Successfully deleted plant ${plantId} from job: ${jobId}`,
        context,
      );

      if (!resource) {
        throw new NotFoundException(
          `Job ${jobId} not found after deleting plant ${plantId}`,
        );
      }
      return JobConverter.fromDocument(resource);
    } catch (error) {
      this.logger.error(
        `Failed to delete plant ${plantId} from job: ${jobId}`,
        context,
        error,
      );
      throw new BadRequestException(`Failed to delete plant: ${error.message}`);
    }
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { JobResponseDto } from '../dto/job/job-response.dto';
import { PlantJobActivateDto } from '../dto/job/plant-job-activate.dto';
import { JobsQueryHelper } from '../dto/job/queries/job.query.helper';
import { DaprService } from './dapr.service';
import { PlantOperationsHelper } from './plant-operations.helper';

@Injectable()
export class ExecuteJobImmediately {
  private readonly logger = new Logger(ExecuteJobImmediately.name);

  public constructor(
    private readonly jobsQueryHelper: JobsQueryHelper,

    private readonly daprService: DaprService,
    private readonly plantHelper: PlantOperationsHelper,
  ) {}

  public async executeJobImmediately(
    jobId: string,
    executeDto: PlantJobActivateDto,
  ): Promise<JobResponseDto> {
    const job = await this.jobsQueryHelper.findJobById(jobId);
    const jobDocument = job as unknown as JobResponseDto;
    // Determine which plants to execute
    const plantsToExecute = this.plantHelper.determinePlantsToProcess(
      executeDto,
      jobDocument,
      jobId,
    );

    if (plantsToExecute.length === 0) {
      this.logger.debug(`[JobsService] No plants to execute for job: ${jobId}`);
      return jobDocument;
    }
    try {
      const now = new Date().toISOString();
      await Promise.allSettled(
        plantsToExecute.map(async (plantId) => {
          try {
            const plant = jobDocument.plants[plantId];
            if (!plant) {
              throw new Error(`Plant ${plantId} not found in job ${jobId}`);
            }

            const immediateJobDocument = {
              ...jobDocument,
              defaultInterval: 0,
              defaultSchedule: { scheduledAt: now },
              plant: {
                id: plantId,
                interval: 0,
                params: plant.params,
                schedule: { scheduledAt: now },
              },
            };
            immediateJobDocument.id = `executeJobImmediately_${immediateJobDocument.id}`;

            await this.daprService.activatePlantJob(
              immediateJobDocument,
              plantId,
            );
            return { plantId, success: true };
          } catch (plantError) {
            this.logger.error(
              `[JobsService] Failed to activate plant ${plantId}:`,
              plantError,
            );
            return { error: plantError.message, plantId, success: false };
          }
        }),
      );
      return jobDocument;
    } catch (error) {
      this.logger.error(
        `[JobsService] Critical error during immediate execution for job: ${jobId}`,
        error,
      );
      throw new BadRequestException(
        `Failed to execute job immediately: ${error.message}`,
      );
    }
  }
}

import { Container } from '@azure/cosmos';
import { Injectable, Logger } from '@nestjs/common';
import { JobExecutionHistoryDto } from '../dto/job-history/job-execution-history.dto';
import { CosmosDatabaseService } from '@/config/cosmos-db/cosmos-database.service';

@Injectable()
export class JobHistoryService {
  private readonly historyContainer: Container;

  private readonly logger = new Logger(JobHistoryService.name);

  public constructor(private readonly cosmosService: CosmosDatabaseService) {
    this.historyContainer =
      this.cosmosService.getContainerJobsExecutionsHistory;
  }

  /**
   * Get execution history for a job
   * @param jobId - The ID of the job to retrieve history for
   * @param limit - The maximum number of history entries to return
   * @returns Promise with an array of job execution history entries
   */
  public async getJobExecutionHistory(
    jobId: string,
    limit = 10,
  ): Promise<Array<JobExecutionHistoryDto>> {
    this.logger.debug(
      `Getting execution history for job ${jobId} (limit: ${limit})`,
    );

    try {
      const query = {
        parameters: [
          { name: '@jobId', value: jobId },
          { name: '@limit', value: limit },
        ],
        query:
          'SELECT * FROM c WHERE c.jobId = @jobId ORDER BY c.timestamp DESC OFFSET 0 LIMIT @limit',
      };

      const { resources } = await this.historyContainer.items
        .query(query)
        .fetchAll();
      this.logger.debug(
        `Retrieved ${resources.length} execution history records for job ${jobId}`,
      );
      return resources as Array<JobExecutionHistoryDto>;
    } catch (error) {
      this.logger.error(
        `Failed to get execution history for job ${jobId}: ${error.message}`,
        error,
      );
      throw error;
    }
  }

  /**
   * Get execution history for a job and plant
   * @param jobId - The ID of the job to retrieve history for
   * @param plantId - The ID of the plant to retrieve history for
   * @param limit - The maximum number of history entries to return
   * @returns Promise with an array of job execution history entries
   */
  public async getJobPlantExecutionHistory(
    jobId: string,
    plantId: string,
    limit = 10,
  ): Promise<Array<JobExecutionHistoryDto>> {
    this.logger.debug(
      `Getting execution history for job ${jobId} and plant ${plantId} (limit: ${limit})`,
    );

    try {
      const query = {
        parameters: [
          { name: '@jobId', value: jobId },
          { name: '@plantId', value: plantId },
          { name: '@limit', value: limit },
        ],
        query:
          'SELECT * FROM c WHERE c.jobId = @jobId AND c.plantId = @plantId ORDER BY c.timestamp DESC OFFSET 0 LIMIT @limit',
      };

      const { resources } = await this.historyContainer.items
        .query(query)
        .fetchAll();

      this.logger.debug(
        `Retrieved ${resources.length} execution history records for job ${jobId} and plant ${plantId}`,
      );
      return resources as Array<JobExecutionHistoryDto>;
    } catch (error) {
      this.logger.error(
        `Failed to get execution history for job ${jobId} and plant ${plantId}: ${error.message}`,
        error,
      );
      throw error;
    }
  }
}

