import { PatchOperation } from '@azure/cosmos';
import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { CosmosDatabaseService } from '../../config/cosmos-db/cosmos-database.service';
import { JobResponseDto } from '../dto/job/job-response.dto';
import { JOB_STATUS, JobStatus } from '../dto/job/job-status.enum';
import { PlantJobActivateDto } from '../dto/job/plant-job-activate.dto';
import { DaprService } from './dapr.service';

@Injectable()
export class PlantOperationsHelper {
  private readonly logger = new Logger(PlantOperationsHelper.name);

  public constructor(
    private readonly cosmosService: CosmosDatabaseService,
    private readonly daprService: DaprService,
  ) {}

  /**
   * Updates the status of a plant in a job
   * @param jobId The ID of the job containing the plant
   * @param plantId The ID of the plant to update
   * @param status The new status to set for the plant
   * @returns The updated job document
   */
  public async updatePlantStatus(
    jobId: string,
    plantId: number,
    status: JobStatus,
  ): Promise<JobResponseDto> {
    this.logger.debug(
      `[PlantOperationsHelper] Updating plant ${plantId} status to ${status} for job ${jobId}`,
    );

    const now = new Date().toISOString();

    try {
      // Prepare patch operations
      const patchOperations: Array<PatchOperation> = [
        {
          op: 'replace' as const,
          path: `/plants/${plantId}/status`,
          value: status,
        },
        {
          op: 'replace' as const,
          path: `/plants/${plantId}/updatedAt`,
          value: now,
        },
        { op: 'replace' as const, path: `/updatedAt`, value: now },
      ];
      const container = this.cosmosService.getContainerJobsDefinition;

      // Apply patch
      const { resource } = await container
        .item(jobId, jobId) // â FIX: add partition key
        .patch(patchOperations);

      if (!resource) {
        throw new NotFoundException(
          `Job ${jobId} not found after updating plant status`,
        );
      }

      this.logger.debug(
        `[PlantOperationsHelper] Successfully updated plant ${plantId} status to ${status} for job ${jobId}`,
      );
      return this.mapDocumentToResponse(resource);
    } catch (error) {
      this.logger.error(
        `[PlantOperationsHelper] Failed to update plant status: job=${jobId}, plant=${plantId}, status=${status}`,
        error,
      );
      throw new BadRequestException(
        `Failed to update plant status: ${error.message}`,
      );
    }
  }

  /**
   * Determines which plants to activate based on the activate DTO
   * @param activateDto The DTO containing plant selection criteria
   * @param jobDocument The job document containing plants
   * @param jobId The ID of the job
   * @param onlyActiveStatus Whether to only consider active plants
   * @returns Array of plant IDs to process
   */
  public determinePlantsToProcess(
    activateDto: PlantJobActivateDto,
    jobDocument: JobResponseDto,
    jobId: string,
    onlyActiveStatus = false,
  ): Array<number> {
    let plantsToProcess: Array<number> = [];

    const plantEntries = Object.entries(jobDocument.plants); // [ [plantId, plantConfig], ... ]

    if (activateDto.allPlants) {
      if (onlyActiveStatus) {
        // Only consider active plants
        const activePlants = plantEntries.filter(
          ([, plant]) => plant.status === JOB_STATUS.active,
        );

        plantsToProcess = activePlants.map(([plantId]) => Number(plantId));
        this.logger.debug(
          `[PlantOperationsHelper] Processing all active plants: [${plantsToProcess.join(', ')}]`,
        );

        if (activePlants.length === 0) {
          this.logger.debug(
            `[PlantOperationsHelper] No active plants found to process`,
          );
        }
      } else {
        plantsToProcess = plantEntries.map(([plantId]) => Number(plantId));
        this.logger.debug(
          `[PlantOperationsHelper] Processing all plants: [${plantsToProcess.join(', ')}]`,
        );
      }
    } else if (activateDto.plantIds && activateDto.plantIds.length > 0) {
      this.logger.debug(
        `[PlantOperationsHelper] Checking specific plants: [${activateDto.plantIds.join(', ')}]`,
      );

      // Verify all plants exist in the job and filter by status if needed
      plantsToProcess = this.validatePlants(
        activateDto.plantIds,
        jobDocument,
        jobId,
        onlyActiveStatus,
      );
    } else {
      throw new BadRequestException(
        'Either allPlants or plantIds must be specified',
      );
    }

    return plantsToProcess;
  }

  /**
   * Validates plants exist in the job and optionally filters by active status
   * @param plantIds Array of plant IDs to validate
   * @param jobDocument The job document containing plants
   * @param jobId The ID of the job
   * @param onlyActiveStatus Whether to only include active plants
   * @returns Array of validated plant IDs
   */
  private validatePlants(
    plantIds: Array<number>,
    jobDocument: JobResponseDto,
    jobId: string,
    onlyActiveStatus = false,
  ): Array<number> {
    const validPlants: Array<number> = [];

    // Verify all plants exist in the job and filter if needed
    for (const plantId of plantIds) {
      const plant = jobDocument.plants[plantId.toString()];
      if (!plant) {
        throw new NotFoundException(
          `Plant ${plantId} not found in job ${jobId}`,
        );
      }

      this.logger.debug(
        `[PlantOperationsHelper] Plant ${plantId} status: ${plant.status}`,
      );

      if (!onlyActiveStatus || plant.status === JOB_STATUS.active) {
        validPlants.push(plantId);
        this.logger.debug(
          `[PlantOperationsHelper] Plant ${plantId} will be processed`,
        );
      } else if (onlyActiveStatus) {
        this.logger.debug(
          `[PlantOperationsHelper] Plant ${plantId} is not active (${plant.status}), skipping`,
        );
      }
    }

    return validPlants;
  }

  /**
   * Filter plants based on their current status
   * @param plantsToProcess Array of plant IDs to filter
   * @param jobDocument The job document containing plants
   * @param targetStatus The status to filter by
   * @param shouldMatch If true, include plants that match the status; if false, include plants that don't match
   * @returns Filtered array of plant IDs
   */
  public filterPlantsByStatus(
    plantsToProcess: Array<number>,
    jobDocument: JobResponseDto,
    targetStatus: JobStatus,
    shouldMatch = false,
  ): Array<number> {
    return plantsToProcess.filter((plantId) => {
      const plant = jobDocument.plants[plantId.toString()];
      if (!plant) {
        this.logger.warn(
          `[PlantOperationsHelper] Plant ${plantId} not found in job document`,
        );
        return false;
      }

      const statusMatches = plant.status === targetStatus;

      if (shouldMatch && statusMatches) {
        return true;
      }

      if (!shouldMatch && !statusMatches) {
        this.logger.debug(
          `[PlantOperationsHelper] Plant ${plantId} status: ${plant.status}, will be processed`,
        );
        return true;
      }

      this.logger.debug(
        `[PlantOperationsHelper] Plant ${plantId} status: ${plant.status}, skipping`,
      );
      return false;
    });
  }

  /**
   * Log summary of operation results
   * @param operationResults Array of operation results with success/failure status
   * @param jobId The ID of the job the operations were performed on
   * @param operation The name of the operation being summarized (e.g., "Activation", "Deactivation")
   */
  public logOperationSummary(
    operationResults: Array<{
      plantId: number;
      success: boolean;
      error?: string;
    }>,
    jobId: string,
    operation: string,
  ): void {
    // Log summary of operation results
    const successfulOperations = operationResults.filter((r) => r.success);
    const failedOperations = operationResults.filter((r) => !r.success);

    this.logger.debug(
      `[PlantOperationsHelper] ${operation} summary for job ${jobId}:`,
    );
    this.logger.debug(
      `[PlantOperationsHelper] - Successful: ${successfulOperations.length} plants [${successfulOperations.map((r) => r.plantId).join(', ')}]`,
    );

    if (failedOperations.length > 0) {
      const failedPlantDetails = failedOperations.map(
        (r) => `${r.plantId}: ${r.error}`,
      );
      this.logger.error(
        `[PlantOperationsHelper] - Failed: ${failedOperations.length} plants [${failedPlantDetails.join(', ')}]`,
      );
    }
  }

  /**
   * Helper to map document to response
   * @param document The document to map to a response DTO
   * @returns The mapped JobResponseDto
   */
  private mapDocumentToResponse(document: JobResponseDto): JobResponseDto {
    this.logger.debug(`Mapping document to response: ${document.id}`);
    return {
      appId: document.appId,
      createdAt: document.createdAt,
      defaultInterval: document.defaultInterval,
      defaultSchedule: document.defaultSchedule,
      description: document.description,
      id: document.id,
      path: document.path,
      plants: document.plants,
      service: document.service,
      type: document.type,
      updatedAt: document.updatedAt,
    };
  }
}

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import * as express from 'express';
import { AppModule } from '@/app.module';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });

  app.use(express.json({ type: 'application/cloudevents+json' }));
  app.use(express.json({ type: 'application/json' }));
  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  const { urlApi } = app.get(UrlApiConfigService);

  const config = new DocumentBuilder()
    .setTitle('Job Scheduler Backend API Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the Job Scheduler Backend microservice and its different endpoints for managing jobs, activation, scheduling, and execution.",
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);

  await app.listen(3000);
}

bootstrap();
